16	func TestSelectedRowWithEmojiMeasuresRenderedWidth(t *testing.T) {
17		for _, name := range []string{"a❤️x", "a\U0001F1EB\U0001F1F7x", "a☀️x"} {
18			m := New(indicatorConfig(nil))
19			m.Resize(60, 10)
20			m.SetItems([]row{{Name: name}, {Name: "zz"}})
21			cursorOn(t, &m, name)
22			want := m.RenderedWidth()
23			if got := ansi.StringWidth(lineOf(t, &m, "a")); got != want {
24				t.Errorf("%q: selected line is %d cells, want %d", name, got, want)
25			}
26		}
