29	// TestSelectedRowSlackIsPaintedWithTheSelectionBackground covers a table wider
30	// than its columns: the gap up to the border must carry ColorTableLineSelected.
31	func TestSelectedRowSlackIsPaintedWithTheSelectionBackground(t *testing.T) {
32		withTrueColor(t)
33		m := New(Config[row]{
34			Key: func(r row) string { return r.Name },
35			Columns: []Column[row]{
36				{Title: "Name", Sizing: SizingFixed, MinWidth: 6, Cell: func(r row) string { return r.Name }},
37			},
38		})
39		m.Resize(60, 10)
40		m.SetItems([]row{{Name: "ab"}})
41		m.SetCursor(0)
42		m.width += 6 // a viewport wider than its columns can fill
43		gap := m.width - 2 - m.RenderedWidth()
44		if gap <= 0 {
45			t.Fatalf("setup: no slack (width %d, rendered %d)", m.width, m.RenderedWidth())
46		}
47		line := lineOf(t, &m, "ab")
48		if got := ansi.StringWidth(line); got != m.width-2 {
49			t.Errorf("selected line is %d cells, want %d", got, m.width-2)
50		}
51		sgr := lipgloss.NewStyle().Background(theme.ColorTableLineSelected).Render("x")
52		sgr = strings.TrimSuffix(strings.TrimPrefix(strings.SplitN(sgr, "x", 2)[0], "\x1b["), "m")
53		reset := "\x1b[m"
54		if !strings.HasSuffix(line, reset) {
55			t.Fatalf("line does not end with a reset: %q", line)
56		}
57		before := line
58		for strings.HasSuffix(before, reset) { // the slack's own reset, then the row's
59			before = strings.TrimSuffix(before, reset)
60		}
61		if !strings.HasSuffix(before, strings.Repeat(" ", gap)) {
62			t.Fatalf("line does not end with the %d-cell slack: %q", gap, line)
63		}
64		if head := strings.TrimSuffix(before, strings.Repeat(" ", gap)); !strings.HasSuffix(head, sgr+"m") {
65			t.Errorf("slack not painted with %q: %q", sgr, line)
66		}
67	}
