	for i := 0; i < b.N; i++ {
		for _, c := range cells {
			_ = f(c, 20)
		}
	}
}
func BenchmarkOld(b *testing.B)  { bench(b, oldFit) }
func BenchmarkNew(b *testing.B)  { bench(b, newFit) }
func BenchmarkFast(b *testing.B) { bench(b, fastFit) }
