package main

import (
	"fmt"
	"math/rand"
	"strings"
	"unicode"
	"unicode/utf8"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"
)

const marker = "…"

type cl struct {
	s string
	w int
}

func clusters(s string) []cl {
	var out []cl
	for len(s) > 0 {
		c, w := ansi.FirstGraphemeCluster(s, ansi.GraphemeWidth)
		if len(c) == 0 {
			c = s[:1]
		}
		out = append(out, cl{c, w})
		s = s[len(c):]
	}
	return out
}

func tail(text string, width int) string {
	cs := clusters(text)
	total := 0
	for _, c := range cs {
		total += c.w
	}
	if total <= width {
		return text
	}
	keep := width - 1
	if keep <= 0 {
		return marker[:len(marker)*min(width, 1)]
	}
	var b strings.Builder
	used := 0
	for _, c := range cs {
		if used+c.w > keep {
			break
		}
		b.WriteString(c.s)
		used += c.w
	}
	return b.String() + marker
}

func head(text string, width int) string {
	cs := clusters(text)
	total := 0
	for _, c := range cs {
		total += c.w
	}
	if total <= width || width <= 0 {
		return text
	}
	if width <= 1 {
		return marker
	}
	keep := width - 1
	used, i := 0, len(cs)
	for i > 0 && used+cs[i-1].w <= keep {
		i--
		used += cs[i].w
	}
	var b strings.Builder
	for _, c := range cs[i:] {
		b.WriteString(c.s)
	}
	return marker + strings.Repeat(" ", keep-used) + b.String()
}

func fit(text string, width int, h bool) string {
	cut := tail(text, width)
	if h {
		cut = head(text, width)
	}
	return lipgloss.NewStyle().Width(width).MaxWidth(width).Inline(true).Render(cut)
}

func main() {
	bad := 0
	corpus := []string{"✔️", "a❤️x", "☀️", "❤️❤️❤️❤️", "1️⃣", "1️⃣2️⃣3️⃣", "x✔️", "ab✔️cd✔️ef", "日本語テキスト", "🇫🇷🇫🇷xx", "\U0001F468‍\U0001F469‍\U0001F467abc", "👍🏽👍🏽ok", "é", "éé", "#️⃣*️⃣", "️abc", "⃣x"}
	pool := []rune("a1#*日ト❤✔☀👍🏽️︎⃣‍́🇫🇷●▲" + "\U000F0219")
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 20000; i++ {
		n := r.Intn(8) + 1
		rs := make([]rune, n)
		for j := range rs {
			rs[j] = pool[r.Intn(len(pool))]
		}
		corpus = append(corpus, string(rs))
	}
	for _, s := range corpus {
		if !utf8.ValidString(s) || strings.IndexFunc(s, unicode.IsControl) >= 0 {
			continue
		}
		for _, h := range []bool{false, true} {
			for w := 1; w <= 12; w++ {
				f := fit(s, w, h)
				if ansi.StringWidth(f) != w {
					bad++
					if bad < 15 {
						fmt.Printf("BAD %q w=%d h=%v -> %q (%d)\n", s, w, h, f, ansi.StringWidth(f))
					}
				}
			}
		}
	}
	fmt.Printf("%q %q %q %q\n", fit("日本語テキスト", 4, true), fit("日本語テキスト", 5, true), fit("x✔️", 2, true), fit("1️⃣2️⃣3️⃣", 4, false))
	fmt.Println("bad", bad, "of", len(corpus))
}
EOF
